-- 前回(00145)に続き、シラバスに載っていそうだが問題集に0件だった概念を追加。
-- マルコフ決定過程・バンディット(強化学習の土台)、Bag of Words(NLPの基本手法)、
-- Multi-Head Attention・Positional Encoding(Transformerの要素技術)。
BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('g-kentei-q55', '3. 機械学習の概要',
   '強化学習の枠組みを定式化したもので、「次の状態は、現在の状態と行動だけで決まり、それ以前の履歴には依存しない」という性質を前提とするものはどれか。',
   NULL::text,
   '["マルコフ決定過程","教師あり学習（回帰）","主成分分析（PCA）","k分割交差検証"]',
   0, '[0]', 'single',
   '{"asked":"『次の状態は現在の状態と行動だけで決まる』という前提で強化学習を定式化した枠組みを選ぶ問題。","point":"『次の状態は今の状態と行動だけで決まる（履歴に依存しない）』と出たら、マルコフ決定過程。","why_asked":"強化学習のQ学習や方策勾配法は解き方（アルゴリズム）だが、マルコフ決定過程はその土台となる問題の定式化（枠組み）。土台とアルゴリズムの区別が問われる。","kid":"今の場所とこれからの一手だけで次に進む場所が決まるすごろく。それまでどんなサイコロの目が出たかは関係ない、というルール。","terms":[["マルコフ決定過程（MDP）","状態・行動・報酬・遷移確率からなり、次の状態が現在の状態と行動だけで決まる（マルコフ性）という前提で強化学習を定式化した枠組み"],["マルコフ性","次に起こることが、現在の状態だけで決まり、それ以前の履歴には依存しないという性質"],["Q学習","マルコフ決定過程を前提に、状態と行動の組み合わせの価値（Q値）を学習して最善の行動を選ぶ強化学習アルゴリズム"]],"eg":"すごろくで、今どのマスにいるかさえ分かれば次の一手が決まり、そこに来るまでの経路は関係ないというルール。","think":"強化学習には『何を前提に問題を組み立てるか（枠組み）』と『その枠組みの中でどう学習するか（アルゴリズム）』の2段階がある。マルコフ決定過程は前者の枠組みで、状態・行動・報酬・遷移確率を使い、『次の状態は現在の状態と行動だけで決まる』というマルコフ性を前提にする。Q学習や方策勾配法は、この枠組みの中で最善の行動を見つけるための具体的な解き方。","vs":"教師あり学習は正解ラベルとの誤差から学ぶ別の学習方式で、状態遷移の前提を扱わない。主成分分析は次元削減、k分割交差検証は評価方法で、どちらも強化学習の定式化とは無関係。","usecase":"ロボット制御やゲームAIなど、行動によって状況が変わっていく問題を数学的に扱うための土台として使う。","opt":["正解。状態・行動・報酬・遷移確率からなり、次の状態が現在の状態と行動だけで決まる（マルコフ性）という前提で強化学習を定式化した枠組み。","正解ラベル付きのデータから入出力の関係を学ぶ学習方式で、状態遷移の前提を扱う枠組みではない。","データの次元を削減する手法で、状態遷移や履歴への依存とは関係ない。","データをk個に分けて評価を安定させる検証方法で、状態遷移の前提を定式化するものではない。"]}'),

  ('g-kentei-q56', '3. 機械学習の概要',
   '「これまで良い結果が出ている選択肢を選び続けるか、まだ試していない選択肢を試すか」というジレンマを扱う、強化学習の基礎となる問題設定はどれか。',
   NULL::text,
   '["多腕バンディット問題","階層的クラスタリング","ランダムフォレスト","k分割交差検証"]',
   0, '[0]', 'single',
   '{"asked":"『良いと分かっている選択肢を選ぶか、まだ試していない選択肢を試すか』のジレンマを扱う問題設定を選ぶ問題。","point":"『活用（知っている中で一番良いものを選ぶ）か探索（試していないものを試すか）のジレンマ』と出たら、多腕バンディット問題。","why_asked":"強化学習の根っこにある『探索と活用のトレードオフ』という考え方そのものを、具体的な問題設定の名前として知っているかを問う。","kid":"行きつけの美味しいお店に行くか、新しい店を試してみるか迷う、あの感じ。","terms":[["多腕バンディット問題（バンディットアルゴリズム）","複数の選択肢の中から報酬を最大化する選択肢を探る、探索と活用のジレンマを扱う問題設定"],["探索と活用のトレードオフ","まだ試していない選択肢を試す（探索）か、良いと分かっている選択肢を選ぶ（活用）かの兼ね合い"],["マルコフ決定過程（MDP）","状態遷移を伴う、より複雑な強化学習の枠組み。バンディットは状態遷移を考えない単純な特殊ケース"]],"eg":"行きつけの美味しい店（活用）に行くか、まだ入ったことのない新しい店（探索）を試すか、外食のたびに迷う状況。","think":"『活用』ばかりだと、本当はもっと良い選択肢を見逃したままになる。『探索』ばかりだと、分かっている良い選択肢を活かせず損をする。多腕バンディット問題は、この2つのバランスをどう取るかを扱う、強化学習の中でも状態遷移を考えない単純な問題設定。","vs":"階層的クラスタリングやランダムフォレストは教師あり/なし学習の具体的な手法で、探索と活用のトレードオフという問題設定そのものとは階層が異なる。k分割交差検証は評価方法で、こちらも別の階層の話。","usecase":"Web広告やレコメンドで、実績のある表示パターンを使い続けるか、新しいパターンを試すかを決めるときに使う考え方。","opt":["正解。複数の選択肢（腕）の中から報酬を最大化する選択肢を探る問題で、『知っている中で一番良いものを選ぶ（活用）』か『まだ知らないものを試す（探索）』かのジレンマを扱う。","似た者同士を段階的にグループにまとめていく教師なし学習の手法で、活用と探索のジレンマを扱う問題設定ではない。","複数の決定木の結果を多数決でまとめる教師あり学習の手法で、活用と探索のジレンマを扱う問題設定ではない。","データをk個に分けて評価を安定させる検証方法で、活用と探索のジレンマを扱うものではない。"]}'),

  ('g-kentei-q57', '6. ディープラーニングの応用例',
   '文章を、単語の並び順を無視して「どの単語がいくつ含まれるか」という出現回数だけで数値化する、自然言語処理の基本的な手法はどれか。',
   NULL::text,
   '["Bag of Words","word2vec（word to vector）","TF-IDF","形態素解析（分かち書き）"]',
   0, '[0]', 'single',
   '{"asked":"単語の並び順を無視し、出現回数だけで文章を数値化する自然言語処理の基本手法を選ぶ問題。","point":"『並び順を無視して、出現回数だけを数える』と出たら、Bag of Words。","why_asked":"word2vecやTF-IDFのような、意味や重要度を捉える手法と比べて、Bag of Wordsは『並び順も重要度も見ず、単語の出現回数だけを見る』という一番単純な土台であることが問われる。","kid":"文章の単語をぜんぶ袋に入れて混ぜてしまい、どの単語が何個入っているかだけを数える方法。並んでいた順番は見ない。","terms":[["Bag of Words","文章を、単語の並び順を無視してどの単語がいくつ含まれるかという出現回数だけで数値化する手法"],["TF-IDF","単語の出現回数に加え、その単語がどれだけ他の文章にも出てくるか（珍しさ）も考慮して重み付けする手法"],["word2vec（word to vector）","単語の意味を、周囲に出てくる単語との関係から低次元のベクトルで表す手法"]],"eg":"文章の単語をぜんぶ袋に入れてシャッフルし、どの単語が何個あったかだけを数えるイメージ。『猫が犬を追いかけた』も『犬が猫を追いかけた』も同じ数え方になってしまう。","think":"Bag of Wordsは単語の『種類と数』しか見ないので、語順による意味の違い（『AがBを追いかけた』と『BがAを追いかけた』）を区別できない。この単純さが、word2vecやTF-IDFのような、語順や重要度まで考慮する手法と対比される最大のポイント。","vs":"word2vecは単語の意味を周囲の単語との関係でベクトル化する手法。TF-IDFは出現回数に加えて単語の珍しさも考慮する重み付け手法で、どちらもBag of Wordsより情報量が多い。形態素解析は文章を単語に分割する前処理であり、数値化の手法そのものではない。","usecase":"スパムメール判定など、単語の出現パターンだけである程度分類できる単純なテキスト分類タスクの土台として使う。","opt":["正解。単語の並び順を無視し、どの単語がいくつ含まれるかという出現回数だけで文章を数値化する手法。","単語の意味を周囲の単語との関係から低次元のベクトルで表す手法で、出現回数だけを数える手法ではない。","単語の出現回数に加え、他の文章にも出てくる珍しさ（希少性）も考慮して重み付けする手法で、出現回数だけを見る手法ではない。","文章を単語や品詞などの単位に分割する処理で、分割した単語を出現回数として数値化する手法そのものではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('g-kentei-j-q48', '5. ディープラーニングの要素技術',
   'Attentionの計算を1回だけでなく複数の異なる視点で並列に行い、その結果をまとめて使うTransformerの仕組みはどれか。',
   NULL::text,
   '["Multi-Head Attention","Positional Encoding（位置情報）","スキップ結合","バッチ正規化"]',
   0, '[0]', 'single',
   '{"asked":"Attentionを複数の異なる視点で並列に行い、結果をまとめて使うTransformerの仕組みを選ぶ問題。","point":"『Attentionを複数の視点で並列に行い、まとめる』と出たら、Multi-Head Attention。","why_asked":"Transformerの要素技術（Attention・Positional Encoding・スキップ結合など）は名前が似た響きで混同しやすく、それぞれ何を解決するための工夫かを区別できるかが問われる。","kid":"同じ文章を、文法担当・意味担当・文脈担当など複数の係の人に同時に読ませて、それぞれの気づきを持ち寄ってまとめるイメージ。","terms":[["Multi-Head Attention","Attentionの計算を複数の異なる視点（ヘッド）で並列に行い、その結果をまとめて使う仕組み"],["Self-Attention","文章内の単語どうしの関係を、自分自身の中で計算するAttentionの一種"],["Positional Encoding","単語の並び順の情報を、各単語のベクトルに追加する仕組み"]],"eg":"同じ文章を、文法担当・意味担当・文脈担当など複数の係に同時に読ませ、それぞれの気づきを持ち寄ってまとめる会議のようなもの。","think":"1つのAttentionだけでは、単語同士の関係を1つの視点でしか捉えられない。Multi-Head Attentionは、同じ入力を複数の異なる視点（ヘッド）で並列にAttention計算し、それぞれが捉えた異なる種類の関係（文法的なつながり、意味的な近さなど）をまとめて使うことで、表現力を高める。","vs":"Positional Encodingは単語の並び順の情報を足す仕組みで、Attentionの視点を増やす仕組みではない。スキップ結合は層を飛び越えて情報を伝える勾配消失対策、バッチ正規化は層の出力をそろえて学習を安定させる仕組みで、どちらもAttentionの並列化とは別の目的。","usecase":"Transformerベースの大規模言語モデル（BERT・GPTなど）で、文章内の多様な関係を同時に捉えるために使われている。","viz":"<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ入力を複数の視点で並列に見て、まとめる</text><rect x=\"20\" y=\"55\" width=\"60\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"50\" y=\"72\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">入力</text><line x1=\"80\" y1=\"68\" x2=\"105\" y2=\"35\" stroke=\"#555e70\"/><line x1=\"80\" y1=\"68\" x2=\"105\" y2=\"68\" stroke=\"#555e70\"/><line x1=\"80\" y1=\"68\" x2=\"105\" y2=\"101\" stroke=\"#555e70\"/><rect x=\"105\" y=\"22\" width=\"66\" height=\"26\" rx=\"4\" fill=\"#3b82f6\" opacity=\"0.15\" stroke=\"#60a5fa\"/><text x=\"138\" y=\"39\" fill=\"#60a5fa\" font-size=\"8\" text-anchor=\"middle\">Head 1</text><rect x=\"105\" y=\"55\" width=\"66\" height=\"26\" rx=\"4\" fill=\"#3b82f6\" opacity=\"0.15\" stroke=\"#60a5fa\"/><text x=\"138\" y=\"72\" fill=\"#60a5fa\" font-size=\"8\" text-anchor=\"middle\">Head 2</text><rect x=\"105\" y=\"88\" width=\"66\" height=\"26\" rx=\"4\" fill=\"#3b82f6\" opacity=\"0.15\" stroke=\"#60a5fa\"/><text x=\"138\" y=\"105\" fill=\"#60a5fa\" font-size=\"8\" text-anchor=\"middle\">Head 3</text><line x1=\"171\" y1=\"35\" x2=\"220\" y2=\"68\" stroke=\"#555e70\"/><line x1=\"171\" y1=\"68\" x2=\"220\" y2=\"68\" stroke=\"#555e70\"/><line x1=\"171\" y1=\"101\" x2=\"220\" y2=\"68\" stroke=\"#555e70\"/><rect x=\"220\" y=\"55\" width=\"60\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"250\" y=\"72\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\">結合</text><line x1=\"280\" y1=\"68\" x2=\"305\" y2=\"68\" stroke=\"#555e70\"/><text x=\"315\" y=\"72\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">出力</text><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">ヘッドごとに違う種類の関係を捉える</text></svg>","opt":["正解。Attentionの計算を複数の異なる視点（ヘッド）で並列に行い、その結果をまとめて使う仕組み。","単語の並び順の情報をベクトルに追加する仕組みで、Attentionを複数の視点で行う仕組みではない。","層の入力を出力に直接足し合わせて、勾配消失を防ぐ仕組みで、Attentionを複数並列に行う仕組みではない。","層の出力の値をそろえて学習を安定させる仕組みで、Attentionを複数の視点で行う仕組みではない。"]}'),

  ('g-kentei-j-q49', '5. ディープラーニングの要素技術',
   'Attentionだけでは単語の並び順の情報が失われてしまうため、各単語のベクトルに並び順の情報を追加するTransformerの仕組みはどれか。',
   NULL::text,
   '["Positional Encoding","Multi-Head Attention","レイヤー正規化","残差接続（スキップ結合）"]',
   0, '[0]', 'single',
   '{"asked":"Attentionだけでは失われる単語の並び順の情報を補うTransformerの仕組みを選ぶ問題。","point":"『Attentionだけでは分からない並び順の情報を足す』と出たら、Positional Encoding。","why_asked":"RNNは単語を順番に処理するので並び順が自然に伝わるが、Transformerは全単語を一度に並列処理するため、この工夫が無いと語順の情報が失われる、という設計上の理由が問われる。","kid":"全員の発言を同時に聞くだけでは発言順が分からなくなるので、一人ひとりに『これは何番目の発言か』という番号札を付けておくようなもの。","terms":[["Positional Encoding","単語の並び順の情報を、各単語のベクトルに追加する仕組み"],["Self-Attention","文章内の単語どうしの関係を並列に計算する仕組みだが、単体では並び順の情報を持たない"],["RNN（Recurrent Neural Network）","単語を1つずつ順番に処理するため、並び順の情報が自然に伝わるネットワーク"]],"eg":"全員が同時に発言する会議では発言順が分からなくなるので、一人ひとりに『これは3番目の発言』という番号札を配っておくようなもの。","think":"RNNは単語を1つずつ順番に処理するので、並び順の情報は自然に伝わる。しかしTransformerはAttentionで全単語を一度に（並列に）処理するため、そのままでは『どの単語が何番目か』という情報が失われてしまう。そこで、各単語のベクトルに並び順を表す情報をあらかじめ足しておくのがPositional Encoding。","vs":"Multi-Head Attentionは関係を捉える視点を増やす仕組み、レイヤー正規化は層の出力をそろえる仕組み、残差接続は勾配消失対策で、どれも並び順の情報を補うものではない。","usecase":"Transformerベースのモデル全般で、単語の順序が意味を左右する文章（語順で意味が変わる言語）を正しく扱うために使われている。","opt":["正解。Attentionだけでは失われてしまう単語の並び順の情報を、各単語のベクトルに追加する仕組み。","Attentionの計算を複数の視点で並列に行う仕組みで、並び順の情報を追加する仕組みではない。","層の出力の値をそろえて学習を安定させる仕組みで、並び順の情報を追加する仕組みではない。","層の入力を出力に直接足し合わせて勾配消失を防ぐ仕組みで、並び順の情報を追加する仕組みではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-j'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
